      { q: "बच्चों ने स्वचालित द्वार की जगह विशेष द्वार से प्रवेश क्यों किया?", options: ["द्वार टूटा था","वे देर से आए थे","उनका समूह-पास बना था","उनके पास टोकन नहीं था और पैसा भी नहीं था"], answer: 2, explain: "बड़े समूह के कारण समूह-पास बना था।", level: 2 },
      { q: "लिफ़्ट का बटन कम ऊँचाई पर क्यों लगाया गया है?", options: ["बच्चों के खेलने के लिए","सजावट के लिए","बचत के लिए","पहिया-कुर्सी वाले भी दबा सकें"], answer: 3, explain: "कर्मचारी ने बताया कि यह सुविधा के लिए है।", level: 2 },
      { q: "कश्मीरी गेट पर बच्चों ने क्या किया?", options: ["गाड़ी बदलकर चाँदनी चौक की मैट्रो ली","वहीं पढ़ाई शुरू की","स्टेशन पर खाना खाया","घर लौट गए"], answer: 0, explain: "वहाँ से भूमिगत प्लेटफार्म पर जाकर चाँदनी चौक वाली गाड़ी ली।", level: 2 },
      { q: "'दंग रह जाना' मुहावरे का अर्थ है –", options: ["नाराज़ हो जाना","हैरान हो जाना","थक जाना","भाग जाना"], answer: 1, explain: "सफ़ाई और सजावट देखकर बच्चे हैरान रह गए।", level: 2 },
      { q: "सिमरन को सुरंग-सी जगह में डर क्यों लगा?", options: ["वहाँ अँधेरा था क्योंकि बत्ती बंद थी","गाड़ी बहुत तेज़ थी","वह भूमिगत मार्ग था","वह अकेली थी"], answer: 2, explain: "भूमिगत प्लेटफार्म सुरंग जैसा लगा, तब गुरु जी ने उसे समझाया।", level: 2 },
      { q: "स्थिति: किसी स्टेशन पर आपकी चप्पल पटरी पर गिर गई। मैट्रो के नियम के अनुसार आपको क्या करना चाहिए?", options: ["खुद पटरी पर कूदना चाहिए","छोड़कर भाग जाना चाहिए","दूसरे बच्चे को भेजना चाहिए","कर्मचारी या अधिकारी को बताना चाहिए"], answer: 3, explain: "पटरी पर गिरी वस्तु खुद उठाने का प्रयास नहीं करना चाहिए।", level: 3 },
      { q: "स्थिति: प्लेटफार्म पर बच्चा गाड़ी देखने के लिए किनारे तक पहुँच गया। आपको क्या करना चाहिए?", options: ["उसे पीली पट्टी के पीछे बुलाना चाहिए","उसे और आगे भेजना चाहिए","फ़ोटो खींचनी चाहिए","अनदेखा करना चाहिए"], answer: 0, explain: "भास्कर को पकड़कर पीली पट्टी के पीछे रहना समझाया गया था।", level: 3 },
      { q: "गाड़ी के अंदर लगातार आने वाले स्टेशनों की जानकारी कैसे मिलती है?", options: ["समाचार-पत्र से","स्पीकर और इलेक्ट्रॉनिक बोर्ड से","पुस्तकालय से","केवल पूछने पर"], answer: 1, explain: "सूचना स्पीकरों और हिंदी-अंग्रेज़ी वाले बोर्ड पर दी जाती है।", level: 3 },
      { q: "इस पाठ से कौन-सी शिक्षा मिलती है?", options: ["तेज़ दौड़ना","शोर मचाना","सार्वजनिक सुविधाओं का नियमों से प्रयोग करना","नियमों की चिंता न करना"], answer: 2, explain: "गुरु जी बार-बार अनुशासन और नियमों की सीख देते हैं।", level: 3 }
